begin;
create extension if not exists pgtap with schema extensions;
select no_plan();
insert into auth.users(id,email,email_confirmed_at) values
 ('f0000000-0000-4000-8000-000000003201','accounting-owner@example.test',now()),
 ('f0000000-0000-4000-8000-000000003202','accounting-staff@example.test',now());
set local role authenticated;
set local "request.jwt.claims"='{"sub":"f0000000-0000-4000-8000-000000003201","role":"authenticated"}';
select set_config('test.a',create_tenant('Accounting AI A','accounting-ai-a',gen_random_uuid())::text,true);
select set_config('test.b',create_tenant('Accounting AI B','accounting-ai-b',gen_random_uuid())::text,true);
select set_config('test.req',gen_random_uuid()::text,true);
select set_config('test.decision',gen_random_uuid()::text,true);
select is(begin_accounting_assistance(current_setting('test.a')::uuid,current_setting('test.req')::uuid,null,'no','model')->>'reserved','true','first attempt reserves');
select is(begin_accounting_assistance(current_setting('test.a')::uuid,current_setting('test.req')::uuid,null,'no','model')->>'status','pending','replay remains pending and does not reserve twice');
select is((select context->>'language' from accounting_ai_attempts where id=current_setting('test.req')::uuid),'no','language is pinned');
select is((select count(*) from usage_events where tenant_id=current_setting('test.a')::uuid and feature='reception_assistance'),1::bigint,'one shared quota unit');
select throws_ok($$select begin_accounting_assistance(current_setting('test.b')::uuid,current_setting('test.req')::uuid,null,'no','model')$$,'P0001','REQUEST_CONFLICT','cross tenant replay denied');
select throws_ok($$select begin_accounting_assistance(current_setting('test.a')::uuid,current_setting('test.req')::uuid,null,'sv','model')$$,'P0001','REQUEST_CONFLICT','language conflict denied');
select throws_ok($$select begin_accounting_assistance(current_setting('test.a')::uuid,gen_random_uuid(),null,'sv','model')$$,'P0001','ASSISTANCE_LIMIT','cooldown applies');
select throws_ok($$select complete_accounting_assistance(current_setting('test.a')::uuid,current_setting('test.req')::uuid,'{"title":"Test"}',0,0)$$,'P0001','INVALID_INPUT','malformed output denied');
select throws_ok($$select complete_accounting_assistance(current_setting('test.a')::uuid,current_setting('test.req')::uuid,'{"rows":[{"key":"grossOre","account":"2999","side":"debit","reason":"Hide difference"}],"warnings":[]}',0,0)$$,'P0001','INVALID_INPUT','unlisted account rejected');
select throws_ok($$select complete_accounting_assistance(current_setting('test.a')::uuid,current_setting('test.req')::uuid,'{"rows":[{"key":"grossOre","account":"1930","side":"debit","reason":"One"},{"key":"grossOre","account":"1910","side":"debit","reason":"Two"}],"warnings":[]}',0,0)$$,'P0001','INVALID_INPUT','duplicate amount key rejected');
select lives_ok($$select complete_accounting_assistance(current_setting('test.a')::uuid,current_setting('test.req')::uuid,'{"rows":[{"key":"grossOre","account":"1930","side":"debit","reason":"Synthetic candidate"}],"warnings":["Review clearing"]}',100,50)$$,'completion stages draft');
select lives_ok($$select complete_accounting_assistance(current_setting('test.a')::uuid,current_setting('test.req')::uuid,'{"rows":[{"key":"grossOre","account":"1930","side":"debit","reason":"Synthetic candidate"}],"warnings":["Review clearing"]}',100,50)$$,'completion replay is immutable');
select is(begin_accounting_assistance(current_setting('test.a')::uuid,current_setting('test.req')::uuid,null,'no','model')->>'status','ready','lost response recovers saved output');
select is((select risk_level from pending_operations where id=current_setting('test.req')::uuid),'low','copy-only approval is low risk');
select lives_ok($$select decide_operation(current_setting('test.a')::uuid,current_setting('test.decision')::uuid,current_setting('test.req')::uuid,'approved','')$$,'owner can use own draft');
select is((select outcome from operation_decisions where id=current_setting('test.decision')::uuid),'executed','draft use executed');
select is((select count(*) from accounting_maps where tenant_id=current_setting('test.a')::uuid),0::bigint,'approval does not publish');
select throws_ok($$delete from accounting_ai_results$$,'42501',null,'API cannot delete result');
select throws_ok($$update accounting_ai_attempts set model='other'$$,'42501',null,'API cannot alter attempt');
-- Complete a result after policy changes: save it for audit, but do not allow use.
select set_config('test.stale',gen_random_uuid()::text,true);
select begin_accounting_assistance(current_setting('test.b')::uuid,current_setting('test.stale')::uuid,null,'sv','model');
select publish_store_policy(current_setting('test.b')::uuid,gen_random_uuid(),null,(current_store_policy(current_setting('test.b')::uuid)->'policy')||'{"assistanceEnabled":true}');
select lives_ok($$select complete_accounting_assistance(current_setting('test.b')::uuid,current_setting('test.stale')::uuid,'{"rows":[],"warnings":["Review old snapshot"]}',100,10)$$,'stale result still settles and saves');
select decide_operation(current_setting('test.b')::uuid,gen_random_uuid(),current_setting('test.stale')::uuid,'approved','');
select is((select outcome from operation_decisions where operation_id=current_setting('test.stale')::uuid),'failed','changed policy prevents applying draft');
-- A map created during generation prevents applying stale suggestions.
select set_config('test.c',create_tenant('Accounting AI C','accounting-ai-c',gen_random_uuid())::text,true);
select set_config('test.mapdraft',gen_random_uuid()::text,true);
select begin_accounting_assistance(current_setting('test.c')::uuid,current_setting('test.mapdraft')::uuid,null,'sv','model');
select set_config('test.map',publish_accounting_map(current_setting('test.c')::uuid,gen_random_uuid(),null,'{"grossOre":{"account":"1930","side":"debit"}}')::text,true);
select complete_accounting_assistance(current_setting('test.c')::uuid,current_setting('test.mapdraft')::uuid,'{"rows":[],"warnings":["Review"]}',100,10);
select decide_operation(current_setting('test.c')::uuid,gen_random_uuid(),current_setting('test.mapdraft')::uuid,'approved','');
select is((select outcome from operation_decisions where operation_id=current_setting('test.mapdraft')::uuid),'failed','concurrent map publication prevents applying stale output');
select throws_ok($$select begin_accounting_assistance(current_setting('test.c')::uuid,gen_random_uuid(),null,'sv','model')$$,'P0001','MAP_CHANGED','stale base rejected before reservation');
select set_config('test.d',create_tenant('Accounting AI D','accounting-ai-d',gen_random_uuid())::text,true);
select set_config('test.saved',publish_accounting_map(current_setting('test.d')::uuid,gen_random_uuid(),null,'{"grossOre":{"account":"1940","side":"debit"}}')::text,true);
select set_config('test.preserve',gen_random_uuid()::text,true);
select begin_accounting_assistance(current_setting('test.d')::uuid,current_setting('test.preserve')::uuid,current_setting('test.saved')::uuid,'sv','model');
select throws_ok($$select complete_accounting_assistance(current_setting('test.d')::uuid,current_setting('test.preserve')::uuid,'{"rows":[{"key":"grossOre","account":"1930","side":"debit","reason":"Overwrite"}],"warnings":[]}',100,10)$$,'P0001','INVALID_INPUT','existing mapped keys cannot be proposed for replacement');
select is((select count(*) from accounting_exports where tenant_id=current_setting('test.a')::uuid),0::bigint,'using a draft creates no export');
select is((select context->'currentMap'->'grossOre'->>'account' from accounting_ai_attempts where id=current_setting('test.preserve')::uuid),'1940','context pins existing account map');
select is((select count(*) from jsonb_object_keys((select context from accounting_ai_attempts where id=current_setting('test.req')::uuid)) k where k not in ('policyId','mapId','language','policy','currentMap','availableKeys','catalogVersion')),0::bigint,'model snapshot contains only bounded accounting context');
reset role;
insert into tenant_members(tenant_id,user_id,role) values(current_setting('test.a')::uuid,'f0000000-0000-4000-8000-000000003202','staff');
set local role authenticated;
set local "request.jwt.claims"='{"sub":"f0000000-0000-4000-8000-000000003202","role":"authenticated"}';
select is((select count(*) from accounting_ai_attempts),0::bigint,'staff cannot read attempts');
select is((select count(*) from accounting_ai_results),0::bigint,'staff cannot read results');
select throws_ok($$select begin_accounting_assistance(current_setting('test.a')::uuid,gen_random_uuid(),null,'sv','model')$$,'P0001','FORBIDDEN','staff cannot spend on accounting generation');
select throws_ok($$select complete_accounting_assistance(current_setting('test.a')::uuid,current_setting('test.req')::uuid,null,0,0)$$,'P0001','FORBIDDEN','staff cannot complete generation');
reset role;
insert into auth.mfa_factors(id,user_id,factor_type,status,created_at,updated_at) values(gen_random_uuid(),'f0000000-0000-4000-8000-000000003201','totp','verified',now(),now());
set local role authenticated;
set local "request.jwt.claims"='{"sub":"f0000000-0000-4000-8000-000000003201","role":"authenticated","aal":"aal1"}';
select is((select count(*) from accounting_ai_results),0::bigint,'MFA is required for reads');
select throws_like($$select begin_accounting_assistance(current_setting('test.a')::uuid,gen_random_uuid(),null,'sv','model')$$,'%AUTH_REQUIRED%','MFA is required for generation');
set local role anon;
select throws_ok($$select begin_accounting_assistance(current_setting('test.a')::uuid,gen_random_uuid(),null,'sv','model')$$,'42501',null,'anonymous cannot invoke engine');
select * from finish();
rollback;

